def transform(grid):
    """Collapse each 3x3 source block to its non-background marker color."""
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range(w // 3)] for _ in range(h // 3)]
    for br in range(h // 3):
        for bc in range(w // 3):
            colors = [grid[r][c]
                      for r in range(br * 3, br * 3 + 3)
                      for c in range(bc * 3, bc * 3 + 3)
                      if grid[r][c] not in (0, 5)]
            if colors:
                out[br][bc] = Counter(colors).most_common(1)[0][0]
    return out
